navbar.css:
:root { --sky: #67c7e8; --sky2: #1598c3; --navy: #102d4f; --ink: #17283a; --muted: #617184; --paper: #f7fbfd; --line: #dceaf0; --white: #fff; --shadow: 0 18px 45px rgba(16,45,79,.1); }
* { box-sizing: border-box; }
a { text-decoration: none; color: inherit; }
.nav nav { display: flex; gap: 22px; align-items: center; font-size: 14px; font-weight: 700; }
.nav nav a.active:not(.nav-cta), .nav nav a:hover { color: var(--sky2); }
.nav-cta { background: var(--navy); padding: 9px 15px; border-radius: 10px; color: white !important; }
.section-head > a { font-weight: 800; color: var(--sky2); }
@media (max-width: 900px) {
.nav nav { display: none; }
.nav nav.open { display: flex; position: absolute; top: 76px; left: 0px; right: 0px; background: white; flex-direction: column; align-items: flex-start; padding: 20px 5%; box-shadow: var(--shadow); }
}

@media (max-width: 700px) {
.admin-code-actions > * { flex: 1 1 0%; }
}

.admin-publish-dialog-actions > * { min-width: 95px; }
@media (max-width: 700px) {
.admin-fullscreen-workspace .admin-code-actions > * { min-width: 0px; padding: 0px 6px; font-size: 10px; }
}

:root { color-scheme: light; --sky: #67c7e8; --sky2: #1598c3; --navy: #102d4f; --ink: #17283a; --muted: #617184; --paper: #f7fbfd; --line: #dceaf0; --white: #fff; --shadow: 0 18px 45px rgba(16,45,79,.1); }
:root[data-theme="dark"] { color-scheme: dark; --sky: #81d8f2; --sky2: #52c6e6; --navy: #e1edf5; --ink: #e3ebf1; --muted: #a7b7c4; --paper: #111a23; --line: #30414f; --white: #1b2833; --shadow: 0 18px 45px rgba(0,0,0,.28); }
html[data-theme="dark"] .primary, html[data-theme="dark"] .nav-cta { background: rgb(23, 103, 130); color: rgb(255, 255, 255) !important; }
html[data-theme="dark"] .nav nav.open { background: rgb(23, 35, 46); border-color: rgb(48, 65, 79); }
@media (max-width: 700px) {
.nav nav.open { top: 76px; }
}

home.css:
:root { --sky: #67c7e8; --sky2: #1598c3; --navy: #102d4f; --ink: #17283a; --muted: #617184; --paper: #f7fbfd; --line: #dceaf0; --white: #fff; --shadow: 0 18px 45px rgba(16,45,79,.1); }
* { box-sizing: border-box; }
a { text-decoration: none; color: inherit; }
.container { width: min(1180px, 92%); margin: auto; }
.topbar-in span { display: flex; align-items: center; gap: 7px; }
.brand > b { width: 45px; height: 45px; border-radius: 13px; background: linear-gradient(135deg,var(--sky),var(--sky2)); display: grid; place-items: center; color: white; font-size: 22px; }
.brand small { display: block; color: var(--muted); font-size: 9px; letter-spacing: 1.4px; }
.nav nav a.active:not(.nav-cta), .nav nav a:hover { color: var(--sky2); }
.hero { background: linear-gradient(135deg, rgb(223, 247, 255), rgb(255, 255, 255) 52%, rgb(238, 250, 255)); overflow: hidden; }
.hero-grid { min-height: 610px; display: grid; grid-template-columns: 1.08fr 0.92fr; align-items: center; gap: 55px; padding: 70px 0px; }
.kicker { font-size: 12px; letter-spacing: 2px; color: var(--sky2); font-weight: 850; }
.hero h1, .page-hero h1 { font-size: clamp(42px, 6vw, 70px); line-height: 1.04; letter-spacing: -2px; color: var(--navy); margin: 14px 0px 20px; }
.hero h1 em { font-style: normal; color: var(--sky2); }
.hero p, .page-hero p { font-size: 18px; color: var(--muted); max-width: 700px; }
.hero-card { min-height: 390px; border-radius: 28px; padding: 32px; background: linear-gradient(155deg,var(--navy),#1d5e87); color: white; box-shadow: var(--shadow); display: flex; flex-direction: column; justify-content: space-between; }
.hero-card span { font-size: 12px; letter-spacing: 2px; color: rgb(159, 227, 247); font-weight: 800; }
.hero-card h2 { font-size: 34px; line-height: 1.15; max-width: 400px; }
.hero-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.hero-stats b { padding: 14px; border: 1px solid rgba(255, 255, 255, 0.17); border-radius: 14px; background: rgba(255, 255, 255, 0.07); font-size: 25px; }
.hero-stats small { display: block; color: rgb(203, 233, 244); font-size: 11px; }
.actions { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 28px; }
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 12px 19px; border-radius: 10px; font-weight: 800; border: 1px solid transparent; }
.primary { background: var(--navy); color: white; }
.secondary { background: white; border-color: rgb(201, 226, 235); color: var(--navy); }
.trust { display: flex; gap: 18px; flex-wrap: wrap; margin-top: 24px; color: var(--muted); font-size: 13px; }
.trust span { display: flex; align-items: center; gap: 5px; }
.trust svg { width: 15px; color: var(--sky2); }
.section-head { display: flex; justify-content: space-between; align-items: end; gap: 25px; margin-bottom: 32px; }
.section-head h2, .feature-grid h2, .detail-layout h2, .prose h2, .contact-grid h2 { font-size: 40px; line-height: 1.12; color: var(--navy); margin: 8px 0px; }
.section-head > a { font-weight: 800; color: var(--sky2); }
.cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; }
.card { background: white; border: 1px solid var(--line); border-radius: 18px; padding: 24px; min-height: 230px; transition: 0.2s; }
.card:hover { transform: translateY(-4px); box-shadow: var(--shadow); }
.card-icon { width: 45px; height: 45px; border-radius: 12px; background: rgb(230, 248, 253); display: grid; place-items: center; color: var(--sky2); font-weight: 900; }
.card h3 { color: var(--navy); font-size: 20px; }
.card p { color: var(--muted); font-size: 14px; }
.card strong { color: var(--sky2); font-size: 13px; }
.soft { background: rgb(238, 250, 255); }
.feature-grid { display: grid; grid-template-columns: 1.4fr repeat(3, 1fr); gap: 18px; }
.feature-grid > div:first-child { padding-right: 30px; }
.feature-grid p, .mini p, .prose p { color: var(--muted); }
.mini { background: white; border: 1px solid var(--line); padding: 22px; border-radius: 18px; }
.mini svg { color: var(--sky2); }
.page-hero h1 { font-size: clamp(40px, 5vw, 62px); }
.other h2 { color: var(--navy); }
.chips span { background: white; border: 1px solid var(--line); border-radius: 999px; padding: 9px 14px; font-size: 13px; }
.detail-list svg { flex: 0 0 auto; color: var(--sky2); }
.detail-list h3 { margin: 0px; color: var(--navy); }
.detail-list p { margin: 5px 0px 0px; color: var(--muted); }
.resource > svg { color: var(--sky2); }
.resource h2 { color: var(--navy); }
.team > b { width: 70px; height: 70px; margin: auto; display: grid; place-items: center; border-radius: 50%; background: linear-gradient(135deg,var(--sky),var(--navy)); color: white; font-size: 25px; }
.team h3 { color: var(--navy); }
.team p { color: var(--muted); }
.contact-info > p { display: flex; gap: 10px; align-items: flex-start; color: var(--muted); }
.contact-info svg { flex: 0 0 auto; color: var(--sky2); margin-top: 5px; }
.footer-grid > div:nth-child(2) { display: flex; flex-direction: column; gap: 8px; }
.footer-grid p { font-size: 13px; }
.footer-grid > div:last-child p { display: flex; gap: 8px; }
.footer-grid .brand + p { max-width: 400px; }
@media (max-width: 900px) {
.hero-grid, .detail-layout, .contact-grid { grid-template-columns: 1fr; }
.cards { grid-template-columns: repeat(2, 1fr); }
.feature-grid { grid-template-columns: 1fr 1fr; }
.hero-grid { min-height: auto; }
.hero-card { min-height: 330px; }
}
@media (max-width: 620px) {
.hero-grid { padding: 55px 0px; }
.cards, .feature-grid, .knowledge-grid, .team-grid, .form-grid, .footer-grid { grid-template-columns: 1fr; }
.section-head { display: block; }
.hero-stats { grid-template-columns: 1fr; }
.trust { display: grid; }
.brand span { font-size: 14px; }
}

.about-hero-copy h1 { max-width: 680px; }
.about-hero-copy p { max-width: 620px; margin-bottom: 28px; }
.about-expertise-card h2, .about-story-copy h2, .about-section-heading h2 { margin: 10px 0px 18px; color: var(--navy); font-size: clamp(28px, 3.5vw, 40px); line-height: 1.16; letter-spacing: -0.7px; }
.about-expertise-card li svg { width: 21px; height: 21px; flex: 0 0 auto; color: var(--sky2); }
.about-story-copy h2 { max-width: 640px; }
.about-story-copy p, .about-section-heading p { color: var(--muted); font-size: 16px; }
.about-principle-icon svg, .about-service-icon svg { width: 22px; height: 22px; }
.about-principle h3, .about-service-card h3 { margin: 0px 0px 5px; color: var(--navy); font-size: 18px; }
.about-principle p, .about-service-card p { margin: 0px; color: var(--muted); font-size: 14px; }
.about-section-heading h2 { margin-bottom: 10px; }
.about-service-card h3 { margin-top: 18px; }
.about-team-heading h2 { margin: 8px 0px; color: var(--navy); font-size: clamp(30px, 4vw, 42px); line-height: 1.15; }
.about-team-heading p { margin: 0px; color: var(--muted); }
.team-card h3 { margin: 18px 0px 8px; font-size: 24px; color: var(--navy); }
.team-card p { margin: 0px; color: var(--muted); }
.team-card span { margin-top: auto; padding-top: 12px; color: var(--sky2); font-weight: 800; }
.bio h2 { margin: 10px 0px; color: var(--navy); }

.admin-login-card h1, .admin-content h1 { margin: 8px 0px; color: rgb(16, 45, 79); font-size: 32px; letter-spacing: -1px; line-height: 1.2; }
.admin-user-chip > span { width: 34px; height: 34px; display: grid; place-items: center; border-radius: 50%; background: rgb(215, 244, 255); color: rgb(18, 108, 139); font-size: 11px; font-weight: 850; }
.admin-user-chip b, .admin-user-chip small { display: block; }
.admin-user-chip b { font-size: 12px; color: white; }
.admin-user-chip small { font-size: 10px; color: rgb(156, 176, 194); }
.admin-session-badge span { width: 7px; height: 7px; border-radius: 50%; background: rgb(55, 174, 115); }
.admin-heading-row h1 { font-size: 36px; }
.admin-heading-row p { margin: 8px 0px 0px; color: rgb(116, 131, 147); font-size: 14px; }
.admin-section-heading h2, .admin-help-card h2 { margin: 0px; color: rgb(24, 53, 80); font-size: 16px; }
.admin-section-heading p { margin: 5px 0px 0px; color: rgb(131, 144, 157); font-size: 12px; }
.admin-preview-copy b { width: 40px; height: 11px; margin-top: 3px; border-radius: 4px; background: rgb(21, 152, 195); }
.admin-layout-meta b, .admin-layout-meta small { display: block; }
.admin-layout-meta b { color: rgb(36, 60, 82); font-size: 12px; }
.admin-layout-meta small { max-width: 550px; margin-top: 3px; color: rgb(130, 144, 156); font-size: 10px; }
.admin-help-card h2 { font-size: 15px; }
.admin-help-card > p { margin: 7px 0px 16px; color: rgb(124, 138, 152); font-size: 11px; line-height: 1.55; }
.admin-selected-layout span { color: rgb(132, 145, 157); }
.admin-selected-layout b { color: rgb(49, 76, 99); }
.admin-footer-note span { margin-left: auto; color: rgb(129, 144, 157); }
.hero--centered .hero-grid { grid-template-columns: 1fr; min-height: 570px; gap: 30px; text-align: center; }
.hero--centered .hero-grid > div:first-child { max-width: 820px; margin: auto; }
.hero--centered .hero-grid > div:first-child > p { margin-left: auto; margin-right: auto; }
.hero--centered .hero-grid .actions, .hero--centered .hero-grid .trust { justify-content: center; }
.hero--centered .hero-card { max-width: 760px; width: 100%; margin: 0px auto; text-align: left; }
.hero--compact .hero-grid { min-height: 430px; padding: 45px 0px; gap: 36px; }
.hero--compact .hero-card { padding: 26px; }
.hero--compact .hero h1 { font-size: clamp(38px, 5vw, 60px); }
@media (max-width: 900px) {
.hero--centered .hero-grid { min-height: auto; padding: 70px 0px; }
.hero--compact .hero-grid { min-height: auto; }
}
@media (max-width: 700px) {
.admin-heading-row h1 { font-size: 30px; }
.admin-footer-note span { width: 100%; margin-left: 24px; }
.hero--centered .hero-grid { padding: 54px 0px; }
.hero--centered .hero-card { padding: 22px; }
.hero--compact .hero-grid { padding: 38px 0px; }
}

.admin-page-picker > span { color: rgb(113, 131, 148); font-size: 9px; font-weight: 850; letter-spacing: 1.3px; }
.admin-code-pane-title > span:first-child { display: flex; align-items: center; gap: 8px; }
.admin-code-pane-title svg { color: rgb(101, 198, 226); }
.admin-live-preview > p { margin: 0px; padding: 9px 12px; border-top: 1px solid rgb(233, 238, 242); background: rgb(255, 255, 255); color: rgb(132, 145, 158); font-size: 10px; }
@media (max-width: 700px) {
.admin-code-actions > * { flex: 1 1 0%; }
.admin-side-item svg { width: 20px; height: 20px; }
}

@media (max-width: 700px) {
.admin-sidebar .admin-side-item svg { width: 20px; height: 20px; }
}

.admin-fullscreen-heading b { color: rgb(24, 53, 80); font-size: 13px; }
.admin-fullscreen-heading span { color: rgb(129, 144, 157); font-size: 10px; }
.admin-publish-dialog h2 { margin: 0px; color: rgb(24, 53, 80); font-size: 21px; letter-spacing: -0.4px; }
.admin-publish-dialog > p { margin: 0px 0px 4px; color: rgb(113, 129, 145); font-size: 12px; line-height: 1.6; }
.admin-publish-dialog > p b { color: rgb(55, 83, 107); }
.admin-publish-dialog-actions > * { min-width: 95px; }
@media (max-width: 700px) {
.admin-fullscreen-heading b { font-size: 11px; }
.admin-fullscreen-heading span { font-size: 9px; }
.admin-header-view svg, .admin-header-logout svg { flex: 0 0 16px; }
.admin-fullscreen-workspace .admin-code-actions > * { min-width: 0px; padding: 0px 6px; font-size: 10px; }
}

:root { color-scheme: light; --sky: #67c7e8; --sky2: #1598c3; --navy: #102d4f; --ink: #17283a; --muted: #617184; --paper: #f7fbfd; --line: #dceaf0; --white: #fff; --shadow: 0 18px 45px rgba(16,45,79,.1); }
:root[data-theme="dark"] { color-scheme: dark; --sky: #81d8f2; --sky2: #52c6e6; --navy: #e1edf5; --ink: #e3ebf1; --muted: #a7b7c4; --paper: #111a23; --line: #30414f; --white: #1b2833; --shadow: 0 18px 45px rgba(0,0,0,.28); }
.theme-toggle svg { color: var(--sky2); }
html[data-theme="dark"] .hero { background: linear-gradient(135deg, rgb(20, 43, 58), rgb(17, 26, 35) 58%, rgb(24, 35, 48)); }
html[data-theme="dark"] .hero-card { background: linear-gradient(155deg, rgb(16, 39, 58), rgb(21, 63, 88)); color: rgb(243, 248, 251); }
html[data-theme="dark"] .hero-card h2 { color: rgb(243, 248, 251); }
html[data-theme="dark"] .hero-card span { color: rgb(159, 227, 247); }
html[data-theme="dark"] .soft, html[data-theme="dark"] .about-services-section { background: rgb(21, 31, 41); }
html[data-theme="dark"] .about-principle-icon, html[data-theme="dark"] .about-service-icon, html[data-theme="dark"] .card-icon { background: rgb(33, 59, 73); }
html[data-theme="dark"] .card, html[data-theme="dark"] .mini, html[data-theme="dark"] .detail-list article, html[data-theme="dark"] .form, html[data-theme="dark"] .resource, html[data-theme="dark"] .team, html[data-theme="dark"] .chips span { background: rgb(27, 40, 51); border-color: rgb(48, 65, 79); color: rgb(227, 235, 241); }
html[data-theme="dark"] .secondary { background: rgb(27, 40, 51); border-color: rgb(64, 81, 94); color: rgb(227, 235, 241); }
html[data-theme="dark"] .primary, html[data-theme="dark"] .nav-cta { background: rgb(23, 103, 130); color: rgb(255, 255, 255) !important; }
html[data-theme="dark"] .admin-login-card h1, html[data-theme="dark"] .admin-publish-dialog h2 { color: rgb(227, 235, 241); }
html[data-theme="dark"] .admin-login-copy, html[data-theme="dark"] .admin-publish-dialog > p { color: rgb(167, 183, 196); }
html[data-theme="dark"] .admin-fullscreen-heading b { color: rgb(227, 235, 241); }
html[data-theme="dark"] .admin-fullscreen-heading span { color: rgb(158, 175, 188); }
html[data-theme="dark"] .admin-page-picker > span { color: rgb(168, 183, 195); }
html[data-theme="light"] .admin-code-pane-title svg { color: rgb(22, 142, 174); }

@scope (.custom-site-page)  {
* { box-sizing: border-box; }
a { text-decoration: none; color: inherit; }
.nav nav a.active:not(.nav-cta), .nav nav a:hover { color: var(--sky2); }
.section-head > a { font-weight: 800; color: var(--sky2); }
@media (max-width: 700px) {
.admin-code-actions > * { flex: 1 1 0%; }
}
.admin-publish-dialog-actions > * { min-width: 95px; }
@media (max-width: 700px) {
.admin-fullscreen-workspace .admin-code-actions > * { min-width: 0px; padding: 0px 6px; font-size: 10px; }
}
:root[data-theme="dark"] { color-scheme: dark; --sky: #81d8f2; --sky2: #52c6e6; --navy: #e1edf5; --ink: #e3ebf1; --muted: #a7b7c4; --paper: #111a23; --line: #30414f; --white: #1b2833; --shadow: 0 18px 45px rgba(0,0,0,.28); }
html[data-theme="dark"] .primary, html[data-theme="dark"] .nav-cta { background: rgb(23, 103, 130); color: rgb(255, 255, 255) !important; }
}
